{
  "drugs": [
    {
      "generic": "azithromycin",
      "plain_purpose": "an antibiotic that treats certain bacterial infections",
      "common_side_effects": ["diarrhea", "nausea", "abdominal pain", "vomiting"],
      "key_warning": "Stop taking it and get medical help right away if you have a severe allergic reaction, liver problems, or severe diarrhea."
    },
    {
      "generic": "acetaminophen",
      "plain_purpose": "a pain reliever and fever reducer",
      "common_side_effects": ["skin rash", "blisters", "skin reddening"],
      "key_warning": "Do not take more than 4,000 mg in 24 hours because it can cause severe liver damage."
    },
    {
      "generic": "metformin",
      "plain_purpose": "a diabetes medicine that helps lower blood sugar when used with diet and exercise",
      "common_side_effects": ["diarrhea", "nausea or vomiting", "gas", "stomach discomfort"],
      "key_warning": "It can cause a rare but serious condition called lactic acidosis; get medical help right away if you feel very tired, cold, dizzy, or have trouble breathing."
    },
    {
      "generic": "atorvastatin",
      "plain_purpose": "a cholesterol medicine that lowers bad cholesterol and reduces the risk of heart attack and stroke",
      "common_side_effects": ["cold-like symptoms", "joint pain", "diarrhea", "pain in arms or legs"],
      "key_warning": "It can cause serious muscle problems that may lead to kidney damage; tell your doctor right away if you have unexplained muscle pain or weakness."
    },
    {
      "generic": "aspirin",
      "plain_purpose": "a pain reliever that also helps prevent blood clots",
      "common_side_effects": ["stomach upset", "heartburn", "nausea", "bleeding"],
      "key_warning": "Children and teenagers with flu or chickenpox should not take it because it can cause Reye's syndrome, a rare but serious illness."
    }
  ]
}
